<?php
require __DIR__ . '/lib.php';
$batch=find_batch((string)($_GET['batch']??''));
$subject=$batch?find_subject($batch,(string)($_GET['subject']??'')):null;
$chapter=$subject?find_chapter($subject,(string)($_GET['chapter']??'')):null;
if(!$batch||!$subject||!$chapter){http_response_code(404);page_header('Chapter not found','library','Not found');echo '<div class="empty"><h2>Chapter not found</h2><a class="primary-btn" href="index.php#rooms">Back to rooms</a></div>';page_footer();exit;}
$state=get_state(); $tab=in_array((string)($_GET['tab']??'lecture'),['lecture','notes','dpp'],true)?(string)$_GET['tab']:'lecture';
$back='batch.php?'.http_build_query(['id'=>$batch['id'],'subject'=>$subject['id']]);
$base=['batch'=>$batch['id'],'subject'=>$subject['id'],'chapter'=>$chapter['id']];
$answers=(array)($state['dpp_answers'][$chapter['id']]??[]); $saved=$state['dpp'][$chapter['id']]??null;
page_header($chapter['name'],'library',$batch['title'].' / '.$chapter['name']);
?>
<a class="back-btn" href="<?=$back?>">← Back to <?=e($subject['name'])?></a>
<div class="chapter-breadcrumb"><a href="batch.php?id=<?=e($batch['id'])?>"><?=e($batch['title'])?></a> <span>/</span> <?=e($subject['name'])?> <span>/</span> <?=e($chapter['name'])?></div>
<div class="detail" style="margin-top:0"><div class="detail-head"><h2><?=e($chapter['name'])?></h2><p><?=e($chapter['duration'])?> · <?=count($chapter['dpp'])?> practice questions · <?=is_done($state,$chapter['id'])?'Chapter complete':'In progress'?></p><div class="tabs"><a class="tab <?=$tab==='lecture'?'active':''?>" href="chapter.php?<?=http_build_query($base+['tab'=>'lecture'])?>">▶ Lecture</a><a class="tab <?=$tab==='notes'?'active':''?>" href="chapter.php?<?=http_build_query($base+['tab'=>'notes'])?>">▤ Notes</a><a class="tab <?=$tab==='dpp'?'active':''?>" href="chapter.php?<?=http_build_query($base+['tab'=>'dpp'])?>">✎ DPP</a></div></div><div class="detail-body">
<?php if($tab==='lecture'): ?>
<div class="resource-box"><div class="resource-kicker">Free public lecture</div><h3>Learn <?=e($chapter['name'])?> with an official public lesson</h3><p>Open the public YouTube search in a new tab and choose the lecture that fits your pace. This app never proxies or republishes paid content.</p><div class="resource-actions"><a class="primary-btn" href="<?=e($chapter['lecture'])?>" target="_blank" rel="noopener">Open lecture search ↗</a><a class="outline-btn" href="chapter.php?<?=http_build_query($base+['tab'=>'notes'])?>">Read notes next</a></div></div>
<?php elseif($tab==='notes'): ?>
<div class="resource-box"><div class="resource-kicker">Official NCERT notes</div><h3><?=e($chapter['notes_title'])?></h3><p>This source document is hosted by NCERT. Open it in a new tab for reading, highlighting or printing.</p><div class="resource-actions"><a class="primary-btn" href="<?=e($chapter['notes'])?>" target="_blank" rel="noopener">Open NCERT PDF ↗</a><a class="outline-btn" href="chapter.php?<?=http_build_query($base+['tab'=>'dpp'])?>">Try the DPP next</a></div><div class="notice" style="margin-top:16px;margin-bottom:0">Notes are opened directly from ncert.nic.in; they are not copied onto this server.</div></div>
<?php else: ?>
<div class="resource-box"><div class="resource-kicker">Daily practice problem</div><h3>Check your understanding</h3><p>Choose an answer. Each selection is submitted as a normal PHP page request, so this is a true multi-page flow.</p>
<?php foreach($chapter['dpp'] as $qi=>$q): $key=(string)$qi; $has=array_key_exists($key,$answers); $selected=$has?(int)$answers[$key]:null; ?><div class="dpp-q"><h4><?=($qi+1)?>. <?=e($q['q'])?></h4><div class="options"><?php foreach($q['options'] as $j=>$option): $cls=''; if($has&&$j===$q['answer'])$cls='correct'; elseif($has&&$j===$selected)$cls='wrong'; ?><form class="option-form" action="progress.php" method="post"><input type="hidden" name="action" value="answer_dpp"><input type="hidden" name="batch" value="<?=e($batch['id'])?>"><input type="hidden" name="subject" value="<?=e($subject['id'])?>"><input type="hidden" name="chapter" value="<?=e($chapter['id'])?>"><input type="hidden" name="question" value="<?=$qi?>"><button class="option option-submit <?=$cls?>" name="answer" value="<?=$j?>"><?=chr(65+$j)?>. <?=e($option)?></button></form><?php endforeach; ?></div><?php if($has): ?><div class="dpp-result"><?=$selected===$q['answer']?'Correct — nice work.':'Not quite. '.e($q['why'])?></div><?php endif; ?></div><?php endforeach; ?>
<?php if($saved): ?><div class="notice success">Current DPP score: <b><?=e($saved['score'])?>%</b>. Keep practising until every answer feels easy.</div><?php endif; ?><div class="mark-row"><form class="simple-form" action="progress.php" method="post"><input type="hidden" name="action" value="toggle_complete"><input type="hidden" name="id" value="<?=e($chapter['id'])?>"><input type="hidden" name="batch" value="<?=e($batch['id'])?>"><input type="hidden" name="subject" value="<?=e($subject['id'])?>"><input type="hidden" name="chapter" value="<?=e($chapter['id'])?>"><button class="outline-btn" type="submit"><?=is_done($state,$chapter['id'])?'Reopen chapter':'Mark chapter complete'?></button></form><span class="tiny-muted">Your progress is private to this browser.</span></div></div>
<?php endif; ?>
</div></div><div class="source-line">Lectures link to public YouTube search results. Notes are from NCERT’s public textbook PDFs.</div>
<?php page_footer(); ?>
